#!/usr/bin/env node
/**
 * Post-refresh sanity check for the two non-screenshot Play Store assets
 * regenerated by generate-play-extras.mjs:
 *
 *   - feature-graphic.png  (must be 1024×500, 24-bit RGB, no alpha)
 *   - icon-512.png         (must be 512×512,  24-bit RGB, no alpha)
 *
 * Play Console rejects the upload if either drifts on dimensions or has an
 * alpha channel re-introduced, so we fail the Android job here — right after
 * generate-play-extras.mjs runs — before the auto-PR opens with bad assets.
 *
 * Uses ImageMagick's `identify` (already required for the screenshot resize
 * step, so no extra dependency).
 *
 * Usage: node scripts/store-screens/verify-play-extras.mjs
 */

import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "..", "..");

const ASSETS = [
  { name: "feature-graphic.png", width: 1024, height: 500 },
  { name: "icon-512.png", width: 512, height: 512 },
];

function inspect(file) {
  const r = spawnSync(
    "magick",
    ["identify", "-format", "%m %w %h %z %[channels]", file],
    { encoding: "utf8" },
  );
  if (r.status !== 0) {
    throw new Error(`identify failed for ${file}: ${r.stderr || r.stdout}`);
  }
  const [format, w, h, depth, channels] = r.stdout.trim().split(/\s+/);
  return {
    format,
    width: Number(w),
    height: Number(h),
    depth: Number(depth),
    channels,
  };
}

function main() {
  const dir = join(ROOT, "assets", "store", "android");
  const errors = [];
  for (const { name, width, height } of ASSETS) {
    const file = join(dir, name);
    if (!existsSync(file)) {
      errors.push(`MISSING: ${file}`);
      continue;
    }
    const info = inspect(file);
    // Play Console expects PNG specifically. `%m` returns the upper-case
    // format magick read out of the file (e.g. "PNG", "JPEG"); reject
    // anything that isn't PNG even if the extension says .png.
    if (info.format !== "PNG") {
      errors.push(
        `WRONG FORMAT: ${file} is ${info.format}, expected PNG`,
      );
      continue;
    }
    if (info.width !== width || info.height !== height) {
      errors.push(
        `WRONG SIZE: ${file} is ${info.width}x${info.height}, expected ${width}x${height}`,
      );
      continue;
    }
    // 24-bit PNG = 8 bits per channel × 3 channels (RGB, no alpha). The
    // Play Console rejects PNG32 (RGBA) for these two assets.
    if (info.depth !== 8) {
      errors.push(
        `WRONG DEPTH: ${file} is ${info.depth}-bit per channel, expected 8 (24-bit RGB)`,
      );
      continue;
    }
    // `%[channels]` returns e.g. "srgb"/"rgb" for valid 24-bit RGB, or
    // "srgba"/"rgba" when alpha is present, or "gray"/"graya" for
    // grayscale. We require an RGB-family channel set with no trailing
    // "a", which guarantees true 24-bit RGB output.
    if (!/^s?rgb$/i.test(info.channels)) {
      errors.push(
        `WRONG CHANNELS: ${file} channels=${info.channels}, expected 24-bit RGB (rgb or srgb, no alpha)`,
      );
      continue;
    }
    console.log(
      `ok  ${name}  ${info.format}  ${info.width}x${info.height}  depth=${info.depth}  channels=${info.channels}`,
    );
  }
  if (errors.length > 0) {
    console.error("\nPlay extras verification failed:");
    for (const e of errors) console.error(`  - ${e}`);
    process.exit(1);
  }
  console.log(`\nAll ${ASSETS.length} Play Store extras verified.`);
}

main();
